@php($displayConclusion=\App\Web\Presentation::conclusion($diagnostic))
@php($terminal=!in_array($diagnostic->status,['PENDING','RUNNING']))
@if($terminal)<span data-terminal hidden></span>@endif
@if($conclusion)<section class="result-banner" data-tone="{{\App\Web\Presentation::tone($displayConclusion['classification'])}}"><x-badge :value="$displayConclusion['classification']"/><h2>{{$displayConclusion['summary']}}</h2><p>Resultado limitado às verificações executadas</p></section>@else<section class="card"><div class="section-head"><h2>Coletando evidências</h2><x-badge :value="$diagnostic->status"/></div><p class="diagnostic-wait" role="status"><span class="diagnostic-spinner" aria-hidden="true"></span>@if($diagnostic->cancel_requested_at)Cancelamento solicitado. Aguarde o encerramento seguro.@elseif($diagnostic->status === 'PENDING' || $steps->every(fn ($step) => in_array($step->status, ['PENDING', 'QUEUED'])))Aguarde. Aguardando o Agent iniciar as verificações.@else<strong>Em execução — aguarde.</strong> O resultado aparecerá automaticamente.@endif</p>@php($settled=$steps->reject(fn($s)=>in_array($s->status,['PENDING','QUEUED','RUNNING']))->count())<div class="progress-track" role="progressbar" aria-label="Progresso das verificações" aria-valuemin="0" aria-valuemax="{{$steps->count()?:1}}" aria-valuenow="{{$settled}}"><span style="width:{{$steps->count()?round($settled/$steps->count()*100):0}}%"></span></div><p class="muted" style="font-size:11px;margin:10px 0 0">{{$settled}} de {{$steps->count()}} verificações finalizadas. @if($diagnostic->cancel_requested_at)Cancelamento solicitado; aguardando encerramento seguro.@else A evidência aparece conforme cada etapa termina.@endif</p></section>@endif
<section class="card diagnostic-timing-card">@include('diagnostics.timing')</section>
<div class="split-grid"><section class="card"><div class="section-head"><h2>Etapas e evidências</h2><x-badge :value="$diagnostic->status"/></div><ol class="step-list">@forelse($steps->groupBy('logical_group') as $group=>$items)<li class="step-row"><div class="step-heading"><h3><span class="step-index">{{$loop->iteration}}</span>{{$group}} @if($items->every(fn ($step) => $step->optional))<span class="chip">Opcional</span>@endif</h3><x-badge :value="\App\Web\Presentation::groupStatus($items)"/></div><div class="step-evidence">@foreach($items as $s)<div class="evidence-line">@include('diagnostics.evidence',['step'=>$s])</div>@endforeach</div><details data-detail-key="{{$group}}"><summary>Detalhes técnicos da verificação</summary>@foreach($items as $s)<p class="muted" style="font-size:11px">{{$s->key}} · {{\App\Web\Presentation::label(\App\Web\Presentation::stepStatus($s))}} · {{\App\Web\Presentation::time($s->started_at,'H:i:s')??'—'}} → {{\App\Web\Presentation::time($s->finished_at,'H:i:s')??'—'}}</p>@if($s->result)<pre>{{json_encode($s->result,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)}}</pre>@endif @if($s->error_code)<p class="error feedback">{{$s->error_code}}</p>@endif @endforeach</details></li>@empty<li class="empty"><p>Plano em preparação. A execução começará quando o Agent estiver disponível.</p></li>@endforelse</ol></section><aside>@if($conclusion)<section class="card"><h2>Próximos passos</h2><ul class="mini-list">@foreach($displayConclusion['next_steps'] as $next)<li><x-icon name="arrow"/><p style="margin:0;color:var(--ink);font-size:12px">{{$next}}</p></li>@endforeach</ul></section>@endif<section class="card"><h2>Escopo desta investigação</h2>@if(in_array($diagnostic->profile?->key, ['SITE_LENTO', 'SITE_NAO_ABRE', 'GOOGLE_YOUTUBE', 'CONTEUDO_LENTO']))<p class="muted">Verifica DNS quando aplicável, TCP 443 e cabeçalhos HTTPS pelo método HEAD. Não mede download, reprodução de vídeo ou carregamento completo da página.</p>@elseif($diagnostic->profile?->key === 'PROBLEMA_DNS')<p class="muted">Consulta registros A e AAAA pelo resolvedor configurado na máquina do Agent.</p>@elseif($diagnostic->profile?->key === 'PERDA_LATENCIA')<p class="muted">Mede uma amostra de cinco pacotes ICMP. Respostas ICMP podem ser filtradas pelo destino; isso não comprova, por si só, indisponibilidade do serviço.</p>@endif<dl class="key-values"><div><dt>Perfil</dt><dd>{{$diagnostic->profile?->display_name}}</dd></div><div><dt>Agent</dt><dd>{{$diagnostic->agent?->name}}</dd></div><div><dt>Início</dt><dd>{{\App\Web\Presentation::time($diagnostic->started_at,'H:i:s')??'Aguardando'}}</dd></div><div><dt>Conclusão</dt><dd>{{\App\Web\Presentation::time($diagnostic->finished_at,'H:i:s')??'Em andamento'}}</dd></div></dl></section>@if(!$terminal)@can('cancel',$diagnostic)<section class="card"><h2>Interromper investigação</h2><p class="muted" style="font-size:12px">As evidências coletadas serão mantidas.</p><form method="post" action="{{route('diagnostics.cancel',$diagnostic)}}" data-confirm="Cancelar este diagnóstico? A execução será interrompida e as evidências já coletadas serão preservadas.">@csrf<button class="button-secondary">Cancelar diagnóstico</button></form></section>@endcan @endif</aside></div>

